const lexicalTentative=new Set(LEXICAL_REVIEWS.tentative.split(' '));
function lexicalReviewFor(w){
 const ids=[w?.id,...(w?.mergedWordIds||[]),...(w?.attestations||[]).map(a=>a.id)];
 const id=ids.find(id=>lexicalClassById.has(id));
 return id?{classes:lexicalClassById.get(id),method:'site-ai-assisted',date:LEXICAL_REVIEWS.date,
   ...(LEXICAL_REVIEWS.structures[id]?{structure:LEXICAL_REVIEWS.structures[id]}:{}),tentative:lexicalTentative.has(id)}:null;
}
function applyLexicalGlossReviews(data){
 for(const w of data.words){
  const r=LEXICAL_REVIEWS.glosses[w.id];if(!r)continue;
  if(!w.lexicalGlossReview)w.lexicalGlossReview={method:'editorial-review',date:r.reviewedAt||LEXICAL_REVIEWS.date,previousZh:w.zh,previousEn:w.en};
  if(r.semanticGloss)w.lexicalGlossReview.semanticGloss=r.semanticGloss;
  w.zh=r.zh;w.en=r.en;w.zhVariants=[...new Set([r.zh,...r.zhAliases||[]])];w.glosses=[...new Set([r.en,...r.enAliases||[]])];
  if(r.formHeadwords)w.formHeadwords=r.formHeadwords.map(form=>({...form}));
  if(w.senses&&!r.keepSharedGloss)w.senses=w.senses.map(s=>({...s,zhBeforeReview:s.zhBeforeReview??s.zh,enBeforeReview:s.enBeforeReview??s.en,zh:r.zh,en:r.en}));
 }
}

